-- Identifier candidates for suppliers that had no identifier on 22.11.2026 (monday item
-- 3375145626). Each supplier's names were searched in the Companies Registrar and the
-- Nonprofits Registrar on data.gov.il, and only registrar names whose distinctive words
-- match the searched name were kept, then checked by eye. A similar name is not proof
-- of the same supplier, so every row enters as a pending candidate for an administrator
-- to accept or dismiss on the identifier candidates screen. Report:
-- reviews/identifier-search-2026-11-22.md in the project files.
--
-- Numbers that already belong to another supplier are left out: they point to duplicate
-- suppliers, which are listed in the report for a merge decision instead.

alter table public.identifier_candidates
  drop constraint identifier_candidates_source_check,
  add constraint identifier_candidates_source_check check (source in (
    'companies_registrar', 'nonprofits_registrar', 'guidestar', 'pool_file'
  ));

