insert into public.identifier_candidates as c (supplier_id, scheme, value, source,
  registrar_name, registrar_status, searched_name)
select f.supplier_id::uuid, f.scheme, f.value, f.source, f.registrar_name,
  f.registrar_status, f.searched_name
from found f
join public.suppliers s on s.id = f.supplier_id::uuid and s.status <> 'merged'
where not exists (
  select 1 from public.supplier_identifiers i
  where i.scheme = f.scheme and i.value = f.value and i.review_status <> 'rejected'
)
-- A pending number from the pool file that the registrar confirms keeps its row and
-- gains the registrar's name and status.
on conflict (supplier_id, scheme, value) do update
set source = excluded.source, registrar_name = excluded.registrar_name,
  registrar_status = excluded.registrar_status
where c.status = 'pending' and c.source = 'pool_file';
